def create_user(
    user_name: str,
    password: Optional[str] = None,
) -> None:
    """Create a new user.

    Args:
        user_name: The name of the user to create.
        password: The password of the user to create.
    """
    client = Client()
    if not password:
        if client.zen_store.type != StoreType.REST:
            password = click.prompt(
                f"Password for user {user_name}",
                hide_input=True,
            )
        else:
            password = click.prompt(
                f"Password for user {user_name}. Leave empty to generate an "
                f"activation token",
                default="",
                hide_input=True,
            )

    try:
        new_user = client.create_user(name=user_name, password=password)

        cli_utils.declare(f"Created user '{new_user.name}'.")
    except EntityExistsError as err:
        cli_utils.error(str(err))
    else:
        if not new_user.active and new_user.activation_token is not None:
            cli_utils.declare(
                f"The created user account is currently inactive. You can "
                f"activate it by visiting the dashboard at the following URL:\n"
                f"{client.zen_store.url}/signup?user={str(new_user.id)}&username={new_user.name}&token={new_user.activation_token}\n"
            )

def populate_obj(self, user):
    # Check if current password is "valid" if Not, rate limit the
    # number of attempts and logout user after too many invalid attempts.
    if not user.validate_password(self.current.data):
        cherrypy.session[CHANGE_PASSWORD_ATTEMPTS] = cherrypy.session.get(CHANGE_PASSWORD_ATTEMPTS, 0) + 1
        attempts = cherrypy.session[CHANGE_PASSWORD_ATTEMPTS]
        if attempts >= CHANGE_PASSWORD_MAX_ATTEMPT:
            cherrypy.session.clear()
            cherrypy.session.regenerate()
            flash(
                _("You were logged out because you entered the wrong password too many times."),
                level='warning',
            )
            raise cherrypy.HTTPRedirect('/login/')
        flash(_("Wrong current password."), level='warning')
    else:
        # Clear number of attempts
        if CHANGE_PASSWORD_ATTEMPTS in cherrypy.session:
            del cherrypy.session[CHANGE_PASSWORD_ATTEMPTS]
        # If Valid, update password
        try:
            user.set_password(self.new.data)
            flash(_("Password updated successfully."), level='success')
        except ValueError as e:
            flash(str(e), level='warning')

def on_part_end(self) -> None:
    message = (MultiPartMessage.PART_END, b"")
    self.messages.append(message)

def match_tag_start(self):
    match = self.match(
        r"""
        \<%     # opening tag

        ([\w\.\:]+)   # keyword

        ((?:\s+\w+|\s*=\s*|".*?"|'.*?')*)  # attrname, = \
                                           #        sign, string expression

        \s*     # more whitespace

        (/)?>   # closing

        """,
        re.I | re.S | re.X,
    )

    if not match:
        return False

    keyword, attr, isend = match.groups()
    self.keyword = keyword
    attributes = {}
    if attr:
        for att in re.findall(
            r"\s*(\w+)\s*=\s*(?:'([^']*)'|\"([^\"]*)\")", attr
        ):
            key, val1, val2 = att
            text = val1 or val2
            text = text.replace("\r\n", "\n")
            attributes[key] = text
    self.append_node(parsetree.Tag, keyword, attributes)
    if isend:
        self.tag.pop()
    elif keyword == "text":
        match = self.match(r"(.*?)(?=\</%text>)", re.S)
        if not match:
            raise exceptions.SyntaxException(
                "Unclosed tag: <%%%s>" % self.tag[-1].keyword,
                **self.exception_kwargs,
            )
        self.append_node(parsetree.Text, match.group(1))
        return self.match_tag_end()
    return True

def run(self, info):
    for tmpl in self.exec_cmd:
        cmd = self.parse_cmd(tmpl, info)
        self.to_screen(f'Executing command: {cmd}')
        _, _, return_code = Popen.run(cmd, shell=True)
        if return_code != 0:
            raise PostProcessingError(f'Command returned error code {return_code}')
    return [], info

